<script setup lang="ts">
import {useAuth} from '../stores/auth'
const auth=useAuth()
import { ref,watch } from 'vue'
import { useRoute,useRouter } from 'vue-router'
import { command,message,desktop } from '../api'
import type {Patient,StudySummary} from '../types'
import {date,age,initials,studyStatus} from '../format'
import PageHeading from '../components/PageHeading.vue'
import PatientForm from '../components/PatientForm.vue'
import EmptyState from '../components/EmptyState.vue'
const router=useRouter()
const selectionMode=ref(false),selected=ref<number[]>([]),bundleOpen=ref(false),bundleName=ref('Объединённый протокол'),bundleBusy=ref(false),bundles=ref<{id:number;name:string;count:number}[]>([]),hideOpen=ref(false)
const route=useRoute(),patient=ref<Patient>(),studies=ref<StudySummary[]>([]),error=ref(''),loading=ref(false),edit=ref(false)
async function load(){loading.value=true;error.value='';patient.value=undefined;try{const result=await command<{patient:Patient;studies:StudySummary[]}>('patient_detail',{id:Number(route.params.id)});patient.value=result.patient;studies.value=result.studies;selected.value=[];bundles.value=await command('patient_bundles',{patientId:result.patient.id})}catch(e){error.value=message(e)}finally{loading.value=false}}
watch(()=>route.params.id,load,{immediate:true})
function toggle(id:number,value:boolean){selected.value=value?[...selected.value,id]:selected.value.filter(v=>v!==id)}
async function createBundle(){if(!patient.value)return;bundleBusy.value=true;try{const id=await command<number>('create_bundle',{patientId:patient.value.id,name:bundleName.value,ids:selected.value});bundleOpen.value=false;await router.push('/bundles/'+id)}catch(e){error.value=message(e)}finally{bundleBusy.value=false}}
async function hide(){if(!patient.value)return;try{await command('set_patient_hidden',{id:patient.value.id,revision:patient.value.revision,hidden:true});await router.push('/')}catch(e){error.value=message(e)}}
</script>
<template><section class="page-content"><RouterLink to="/" class="back-link no-print"><UIcon name="i-lucide-arrow-left"/>Все пациенты</RouterLink><UAlert v-if="error" color="error" :description="error"/><div v-if="loading" class="loading-state">Открываем карточку…</div><template v-if="patient"><PageHeading :title="patient.name" :description="`Карточка № ${patient.id}`"><UButton size="lg" v-if="auth.admin" color="neutral" variant="ghost" icon="i-lucide-archive" @click="hideOpen=true">Скрыть карточку</UButton><UButton size="lg" color="neutral" variant="outline" icon="i-lucide-pencil" :disabled="!desktop||!auth.canWrite" @click="edit=true">Изменить карточку</UButton><UButton size="lg" :to="'/studies/new/'+patient.id" icon="i-lucide-plus" :disabled="!desktop||!auth.canWrite">Новое исследование</UButton></PageHeading>
<div class="patient-overview"><span class="patient-avatar avatar-large" :class="patient.gender==='F'?'avatar-rose':'avatar-blue'">{{initials(patient.name)}}</span><dl class="overview-facts"><div><dt>Дата рождения</dt><dd>{{date(patient.birthdate)}} <span>{{age(patient.birthdate)}}</span></dd></div><div><dt>Пол</dt><dd>{{patient.gender==='F'?'Женский':'Мужской'}}</dd></div><div><dt>Адрес</dt><dd>{{[patient.city,patient.street,patient.house&&'д. '+patient.house,patient.flat&&'кв. '+patient.flat].filter(Boolean).join(', ')||'Не указан'}}</dd></div></dl></div>
<div class="section-heading"><h2>История исследований <span>{{studies.length}}</span></h2><span>Сначала новые</span></div><div v-if="auth.canWrite" class="bundle-toolbar no-print"><UButton v-if="!selectionMode" variant="outline" icon="i-lucide-files" @click="selectionMode=true">Объединить для печати</UButton><template v-else><span>Выбрано {{selected.length}} из 20</span><UButton :disabled="selected.length<2||selected.length>20" @click="bundleOpen=true">Создать объединённый протокол</UButton><UButton color="neutral" variant="ghost" @click="selectionMode=false;selected=[]">Отмена</UButton></template></div><div class="history-list"><div v-for="study in studies" :key="study.id" class="history-row"><UCheckbox v-if="selectionMode" :model-value="selected.includes(study.id)" @update:model-value="toggle(study.id,Boolean($event))" :disabled="!['final','legacy:1'].includes(study.status)" :aria-label="'Выбрать исследование № '+study.id"/><RouterLink :to="'/studies/'+study.id" class="history-row-link"><div class="history-date"><strong>{{date(study.date)}}</strong><span>№ {{study.id}}</span></div><span class="document-icon"><UIcon name="i-lucide-file-text"/></span><div class="history-title"><h3>{{study.title}}</h3><p>{{study.doctor||'Врач не указан'}}</p></div><UBadge :color="study.origin==='legacy'?'neutral':study.status==='draft'?'warning':'primary'" variant="subtle">{{studyStatus(study.status)}}</UBadge><UIcon name="i-lucide-chevron-right" class="text-slate-400"/></RouterLink></div></div><EmptyState v-if="!studies.length" title="История пока пуста" description="Создайте первое исследование для этого пациента." icon="i-lucide-file-plus-2"/>
<section v-if="bundles.length" class="mt-8"><h2 class="text-lg font-semibold mb-4">Объединённые протоколы</h2><RouterLink v-for="bundle in bundles" :key="bundle.id" :to="'/bundles/'+bundle.id" class="history-row bg-white"><UIcon name="i-lucide-files"/><span>{{bundle.name}}</span><span class="text-slate-600">{{bundle.count}} исследований</span></RouterLink></section><UModal v-model:open="bundleOpen" title="Объединить исследования для печати" description="Оригиналы останутся отдельными записями"><template #body><UFormField label="Название"><UInput v-model="bundleName" class="w-full"/></UFormField><p class="text-slate-600 mt-4">Будут объединены только выбранные завершённые исследования этого пациента, в порядке истории.</p></template><template #footer><UButton color="neutral" variant="ghost" @click="bundleOpen=false">Отмена</UButton><UButton :loading="bundleBusy" @click="createBundle">Создать</UButton></template></UModal><UModal v-model:open="hideOpen" title="Скрыть карточку из общего списка?" :description="patient.name"><template #body><p>Карточка и её история сохранятся. Администратор сможет вернуть её через раздел «База и копии».</p></template><template #footer><UButton color="neutral" variant="ghost" @click="hideOpen=false">Отмена</UButton><UButton color="warning" @click="hide">Скрыть карточку</UButton></template></UModal><PatientForm :patient="patient" v-model:open="edit" @saved="load"/></template></section></template>
